-- Renders every app's config from PALETTE and FONT. ${name} placeholders are filled from
-- PALETTE, FONT and VARS; ${rgb_name} gives "r,g,b" for KDE. Generated files are marked.
local HOME = os.getenv("HOME")

local function json(s) return (s:gsub("\\", "\\\\"):gsub('"', '\\"')) end
local function rgb(hex)
    return string.format("%d,%d,%d", tonumber(hex:sub(1, 2), 16), tonumber(hex:sub(3, 4), 16), tonumber(hex:sub(5, 6), 16))
end

local VARS = {
    power      = json(POWER_MENU),
    network    = json(APPS.network),
    mixer      = json(APPS.mixer),
    lock       = IDLE.lock,
    screen_off = IDLE.screen_off,
}

local function lookup(k)
    local base = k:match("^rgb_(.+)$")
    if base then return PALETTE[base] and rgb(PALETTE[base]) end
    local v = PALETTE[k] or FONT[k] or VARS[k]
    return v and tostring(v)
end

local changed = false
local function render(rel, header, body)
    local path = HOME .. "/.config/" .. rel
    os.execute("mkdir -p '" .. path:match("^(.*)/") .. "'")
    local text = header:format("generated by slate from ~/.config/hypr/slate; edit the Lua, not this file")
        .. "\n" .. body:gsub("%${([%w_]+)}", lookup)
    local f = io.open(path, "r")
    local old = f and f:read("*a")
    if f then f:close() end
    if old ~= text then
        f = io.open(path, "w")
        if f then f:write(text); f:close(); changed = true end
    end
end

