---------------------------------------------------------------- Qt/KDE apps (Dolphin) read kdeglobals
local kde = { "[General]\nColorScheme=Slate\n" }
local function group(name, bg, alt, fg)
    kde[#kde + 1] = string.format(
        "[Colors:%s]\nBackgroundNormal=${rgb_%s}\nBackgroundAlternate=${rgb_%s}\nForegroundNormal=${rgb_%s}\n" ..
        "ForegroundInactive=${rgb_muted}\nForegroundActive=${rgb_accent}\nForegroundLink=${rgb_accent}\n" ..
        "ForegroundNegative=${rgb_urgent}\nForegroundPositive=${rgb_good}\nDecorationFocus=${rgb_accent}\nDecorationHover=${rgb_accent}\n",
        name, bg, alt, fg)
end
group("Window", "surface", "overlay", "text")
group("View", "bg", "surface", "text")
group("Button", "surface", "overlay", "text")
group("Header", "surface", "overlay", "text")
group("Tooltip", "surface", "overlay", "text")
group("Complementary", "surface", "overlay", "text")
group("Selection", "accent", "accent", "bg")
render("kdeglobals", "# %s", table.concat(kde, "\n"))

-- Live-reload the running bar and notifications after `hyprctl reload`
if changed then
    hl.on("config.reloaded", function()
        hl.exec_cmd("pkill -SIGUSR2 -x waybar; makoctl reload; pkill -x hypridle; hypridle")
    end)
end
